// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address caller, address target, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(target != address(0));
        vm.assume(caller != target);
        vm.assume(amount > 0 && amount <= type(uint128).max);

        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();

        vm.prank(caller);
        uint256 val = c.getBalance(target);
        assertTrue(val == c.getBalance(target));
    }
}
